/// Merges overlapping (and touching) [start, end] intervals, sorted by start.
pub fn merge_intervals(xs: List[List[Int]]) -> List[List[Int]] {
  let sorted = xs.sort_by(fn(iv) => iv.get_or(0, 0))
  var out: List[List[Int]] = []
  var cur_s = 0
  var cur_e = 0
  var have = false
  for iv in sorted {
    let s = iv.get_or(0, 0)
    let e = iv.get_or(1, 0)
    if not have {
      cur_s = s
      cur_e = e
      have = true
    } else if s <= cur_e {
      if e > cur_e {
        cur_e = e
      }
    } else {
      out = out.push([cur_s, cur_e])
      cur_s = s
      cur_e = e
    }
  }
  if have {
    out = out.push([cur_s, cur_e])
  }
  return out
}
